<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['guardar'])){$pdo->prepare('INSERT INTO gastos(fecha,categoria,concepto,monto,metodo,responsable,cotizacion_id,notas) VALUES(?,?,?,?,?,?,?,?)')->execute([epost('fecha',date('Y-m-d')),epost('categoria','Otros'),epost('concepto'),efloat('monto'),epost('metodo'),epost('responsable'),((int)($_POST['cotizacion_id']??0))?:null,epost('notas')]);}if(isset($_POST['eliminar']))$pdo->prepare('DELETE FROM gastos WHERE id=?')->execute([(int)$_POST['id']]);ego('gastos.php?mes='.urlencode($_POST['mes']??date('Y-m')));}
$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$mes))$mes=date('Y-m');$ini=$mes.'-01';$fin=date('Y-m-t',strtotime($ini));$s=$pdo->prepare('SELECT g.*,c.folio,c.cliente FROM gastos g LEFT JOIN cotizaciones c ON c.id=g.cotizacion_id WHERE g.fecha BETWEEN ? AND ? ORDER BY g.fecha DESC,g.id DESC');$s->execute([$ini,$fin]);$rows=$s->fetchAll();$sum=array_sum(array_map(fn($r)=>(float)$r['monto'],$rows));$cots=srnu_get_cotizaciones_select();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gastos · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('finanzas');?><main class="w"><div class="srnu-page-heading"><div><h1>Gastos del negocio</h1><p>Renta, luz, agua, nómina, materiales, envíos y gastos por trabajo.</p></div><a class="btn light" href="finanzas.php">← Finanzas</a></div><div class="kpi-grid"><div class="kpi"><small>Gasto del mes</small><strong><?=emoney($sum)?></strong></div><div class="kpi"><small>Registros</small><strong><?=count($rows)?></strong></div></div><section class="panel" style="padding:18px;margin-top:16px"><form method="post" class="erp-form cols-4"><input type="hidden" name="mes" value="<?=eh($mes)?>"><input type="date" name="fecha" value="<?=date('Y-m-d')?>"><select name="categoria"><option>Materiales</option><option>Renta</option><option>Luz</option><option>Agua</option><option>Nómina</option><option>Herramientas</option><option>Envíos</option><option>Publicidad</option><option>Comisiones</option><option>Otros</option></select><input name="concepto" required placeholder="Concepto"><input type="number" step="0.01" min="0" name="monto" required placeholder="Monto"><select name="metodo"><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option><option>Otro</option></select><select name="responsable"><option value="">General</option><option>Sergio</option><option>Ricardo</option><option>Tomás</option></select><select name="cotizacion_id"><option value="">Sin cotización</option><?php foreach($cots as $c):?><option value="<?=$c['id']?>"><?=eh(srnu_cotizacion_label($c))?></option><?php endforeach;?></select><input name="notas" placeholder="Notas"><button class="btn blue" name="guardar" value="1">Registrar gasto</button></form></section><form class="toolbar" style="margin:16px 0"><input type="month" name="mes" value="<?=eh($mes)?>"><button class="btn">Ver mes</button></form><section class="tablebox"><table><thead><tr><th>Fecha</th><th>Categoría</th><th>Concepto</th><th>Responsable</th><th>Cotización</th><th>Monto</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=edate($r['fecha'])?></td><td><?=eh($r['categoria'])?></td><td><?=eh($r['concepto'])?><div class="muted"><?=eh($r['notas'])?></div></td><td><?=eh($r['responsable'])?></td><td><?=eh(trim(($r['folio']??'').' '.($r['cliente']??'')))?></td><td><?=emoney($r['monto'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="mes" value="<?=eh($mes)?>"><button class="btn danger" name="eliminar" value="1" onclick="return confirm('¿Eliminar gasto?')">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
